CREATE TABLE CORE.T_DIM_CAL_DAY_1 (
	CAL_DT DATE NOT NULL COMMENT 'The day represented as a calendar_1 date of the form YYYY-MM_1-DD. YYYY is the calendar_1 year, MM_1 (between 1 and 12) the calendar_1 month and DD the day of the calendar_1 month (between 1 and 31). ',
	CY NUMBER(38,0)  COMMENT 'The calendar_1 year as a number in the form YYYY. Eg. 2019',
	BUS_YEAR NUMBER(38,0)  COMMENT 'The business year as a number in the form YYYY. Eg. 2019',
	CY_MONTH NUMBER(38,0)  COMMENT 'The calendar_1 month as a number of the form YYYYMM, where YYYY is the calendar_1 year and MM_1 is month of the calendar_1 year.',
	MONTH_OF_YEAR NUMBER(38,0)  COMMENT 'The month of the calendar_1 year as a number using the convention January = 1 ... December = 12.',
	MONTH_OF_BUS_YEAR NUMBER(38,0)  COMMENT 'The month of the (Lidl) business year (starting in March) as a number using the convention March = 1, April = 2 ... December = 10, January = 11, February = 12. ',
	MONTH_OF_YEAR_SHORT_NAME VARCHAR(100)  COMMENT 'The short name / abbreviation for month of the year in group language, i.e. in German.',
	MONTH_OF_YEAR_SHORT_NAME_DE VARCHAR(100) COMMENT 'The short name / abbreviation for month of the year in German.',
	MONTH_OF_YEAR_SHORT_NAME_EN VARCHAR(100) COMMENT 'The short name / abbreviation for month of the year in English.',
	MONTH_OF_YEAR_NAME VARCHAR(100)  COMMENT 'The full name for the month of the year in group language, i.e. in German.',
	MONTH_OF_YEAR_NAME_DE VARCHAR(100) COMMENT 'The full name for the month of the year in German.',
	MONTH_OF_YEAR_NAME_EN VARCHAR(100) COMMENT 'The full name for the month of the year in English.',
	DAY_OF_MONTH NUMBER(38,0)  COMMENT 'The sequence number of the day within the month. Simply the calendar_1 day number in the calendar_1 month. A number between 1 and 31.   ',
	CY_QUARTER NUMBER(38,0),
	CY_WEEK NUMBER(38,0)  COMMENT 'The week to which this week belongs, as a number in the form YYYYWW. YYYY is the year of the week and WW is the number of the week within the calendar_1 year. Week 1 is the first week in the calendar_1 year containing at least 4 days.',
	WEEK_OF_YEAR NUMBER(38,0)  COMMENT 'The number of the week within the calendar_1 year, to which this day belongs., i.e. a number between 1 and 53. Week 1 is the first week in the calendar_1 year containing at least 4 days, therefore the first week containing a Thursday.',
	DAY_OF_WEEK NUMBER(38,0)  COMMENT 'The day of the week as a number using the convention Mon=1 ... Sun=7. I.e. the sequence of the weekday within the week starting on a Monday.',
	DAY_OF_WEEK_SHORT_NAME VARCHAR(100)  COMMENT 'The abbreviation for the weekday in group language, i.e. in German, ',
	DAY_OF_WEEK_SHORT_NAME_DE VARCHAR(100) COMMENT 'The abbreviation for the weekday in German, ',
	DAY_OF_WEEK_SHORT_NAME_EN VARCHAR(100) COMMENT 'The abbreviation for the weekday in English.',
	DAY_OF_WEEK_NAME VARCHAR(100)  COMMENT 'The full name for day of the week in group language, i.e. in German.',
	DAY_OF_WEEK_NAME_DE VARCHAR(100) COMMENT 'The full name for day of the week in German.',
	DAY_OF_WEEK_NAME_EN VARCHAR(100) COMMENT 'The full name for day of the week in English. ',
	DAY_OF_CY NUMBER(38,0)  COMMENT 'The sequence number of the day within in the calendar_1 year. A number between 1 and 366. January 1st will always be 1 and December 31st always 365 or 366 for leap years.',
	DAY_OF_BUS_YEAR NUMBER(38,0)  COMMENT 'The sequence number of the day within in the business year. A number between 1 and 366. March 1st will always be 1, February 28th always 365 and February 29th always 366.',
	CAL_DT_PREV_1D DATE  COMMENT 'The calendar_1 date of the same day 1 day ago,',
	CAL_DT_PREV_1W DATE  COMMENT 'The calendar_1 date of the same day 1 week ago, ',
	CAL_DT_PREV_1M DATE  COMMENT 'The calendar_1 date of the same day 1 month ago. Calculated by offsetting cal_dt by -1 month. If the corresponding day does not exist in the target month then Null is returned. ',
	CAL_DT_PREV_1Y DATE  COMMENT 'The calendar_1 date of the same day 1 year ago. Calculated by subtracting 12 months. If there are insufficient days in the target month, the last day in the month is returned.',
	CAL_DT_PREV_2Y DATE  COMMENT 'The calendar_1 date of the same day 2 years ago. Calculated by subtracting 24 months. If there are insufficient days in the target month the last day in the month is returned. ',
	CAL_DT_PREV_3Y DATE  COMMENT 'The calendar_1 date of the same day 3 years ago. Calculated by subtracting 36 months. If there are insufficient days in the target month the last day in the month is returned.',
	CAL_DT_PREV_4Y DATE  COMMENT 'The calendar_1 date of the same day 4 years ago. Calculated by subtracting 48 months. If there are insufficient days in the target month the last day in the month is returned. ',
	CAL_DT_PREV_5Y DATE  COMMENT 'The calendar_1 date of the same day 5 years ago. Calculated by subtracting 60 months. If there are insufficient days in the target month the last day in the month is returned.',
	CAL_DT_SWDAY_PREV_1M DATE  COMMENT 'The calendar_1 date of the same weekday (approximately) 1 month ago. Calculated by offsetting cal_dt by -28 (days) i.e. 4 weeks. ',
	CAL_DT_SWDAY_PREV_1Y DATE  COMMENT 'The calendar_1 date of the same weekday (approximately) 1 year ago.  Calculated by offsetting cal_dt by -364 (days) ie. 52 weeks. ',
	CAL_DT_SWDAY_PREV_2Y DATE  COMMENT 'The calendar_1 date of the same weekday (approximately) 2 years ago. Calculated by offsetting cal_dt by -728 (days) i.e. 104 weeks. ',
	CAL_DT_SWDAY_PREV_3Y DATE  COMMENT 'The calendar_1 date of the same weekday (approximately) 3 years ago. Calculated by offsetting cal_dt by -1092 (days) i.e. 156 weeks. ',
	CAL_DT_SWDAY_PREV_4Y DATE  COMMENT 'The calendar_1 date of the same weekday (approximately) 4 years ago. Calculated by offsetting cal_dt by -1456 (days) i.e. 208 weeks. ',
	CAL_DT_SWDAY_PREV_5Y DATE  COMMENT 'The calendar_1 date of the same weekday (approximately) 5 years ago. Calculated by offsetting cal_dt by -1820 (days) i.e. 260 weeks. ',
	FIRST_DAY_OF_WEEK_FG BOOLEAN  COMMENT 'An indicator showing, if this is the first day of the containing week.',
	LAST_DAY_OF_WEEK_FG BOOLEAN  COMMENT 'An indicator showing, if this is the last day of the containing week.',
	FIRST_DAY_OF_MONTH_FG BOOLEAN  COMMENT 'An indicator showing, if this is the first day of the containing month.',
	LAST_DAY_OF_MONTH_FG BOOLEAN  COMMENT 'An indicator showing, if this is the last day of the containing month.',
	FIRST_DAY_OF_CY_FG BOOLEAN  COMMENT 'An indicator showing, if this is the first day of the containing calendar_1 year.',
	LAST_DAY_OF_CY_FG BOOLEAN  COMMENT 'An indicator showing, if this is the last day of the containing calendar_1 year.',
	FIRST_DAY_OF_BUS_YEAR_FG BOOLEAN  COMMENT 'An indicator showing, if this is the first day of the containing business year.',
	LAST_DAY_OF_BUS_YEAR_FG BOOLEAN  COMMENT 'An indicator showing, if this is the last day of the containing business year.',
	CAL_DT_OFFSET NUMBER(38,0) COMMENT 'The difference in days between this day and the current date. So if the current date is 2019-05-02, then this offset is 0 for 2019-05-02, -1 for 2019-05-01 and +1 for 2019-05-03.',
	CY_WEEK_OFFSET NUMBER(38,0) COMMENT 'The difference in weeks between this week and the current week. So if current week is 202053 then the offset is 0 for 202053, -1 for 202052 and +1 for 202101.  ',
	CY_MONTH_OFFSET NUMBER(38,0) COMMENT 'The difference in months between this calendar_1 month and the current calendar_1 month. So if current calendar_1 month is 201901 then the offset is 0 for 201901, -1 for 201812 and +1 for 201902.',
	CY_OFFSET NUMBER(38,0) COMMENT 'The difference in years between this calendar_1 year and the current calendar_1 year. So if the current calendar_1 year is 2019 then the offset is 0 for 2019, -1 for 2018 and +1 for 2020.',
	BUS_YEAR_OFFSET NUMBER(38,0) COMMENT 'The difference in years between this business year and the current business year. So if the current business year is 2019 then the offset is 0 for 2019, -1 for 2018 and +1 for 2020. ',
	CY_QUARTER_OFFSET NUMBER(38,0),
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was inserted into the table.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was last modified. (In case the record has not been modified since its creation, dwh_updated is identical to dwh_created.)' ,
	DWH_SRC_FILE_NAME                   VARCHAR(255)    COMMENT 'The path and the name of the file(s) from which this record was loaded.',
    SRC_FILE_TMSP                       TIMESTAMP_LTZ   COMMENT 'The point in time when this record was extracted from the source.',
    CONSTRAINT PK_T_DIM_CAL_DAY PRIMARY KEY (CAL_DT) NOT ENFORCED
)COMMENT='The main date dimension for all days in the calendar.'
;